/* Alloxentric SupportHub — widget embebible (RF-29). Autocontenido, sin dependencias.
   Uso: <script src=".../widget.min.js" data-tenant-id="<slug>" data-primary-color="#4F46E5" data-position="right" defer></script>
   Crea un botón flotante y, al abrirlo, un iframe con la página pública /chat/<slug>?embed=1 del mismo origen que este script. */
(function(){
  var s=document.currentScript;
  if(!s||window.__alloxentricWidget)return;
  var slug=s.getAttribute("data-tenant-id");
  if(!slug){console.error("[Alloxentric] Falta data-tenant-id");return}
  window.__alloxentricWidget=1;
  var base=s.getAttribute("data-base-url")||new URL(s.src,location.href).origin,
      color=s.getAttribute("data-primary-color")||"#4F46E5",
      side=s.getAttribute("data-position")==="left"?"left":"right",
      label=s.getAttribute("data-agent-name")||"Soporte",
      z="2147483000",frame=null,open=false,dot=null;

  function css(el,o){for(var k in o)el.style[k]=o[k]}
  var btn=document.createElement("button");
  btn.type="button";btn.setAttribute("aria-label","Abrir chat con "+label);btn.setAttribute("aria-expanded","false");
  btn.innerHTML='<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>';
  css(btn,{position:"fixed",bottom:"20px",width:"56px",height:"56px",border:"0",borderRadius:"50%",cursor:"pointer",background:color,boxShadow:"0 6px 20px rgba(0,0,0,.25)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:z});
  btn.style[side]="20px";
  dot=document.createElement("span");dot.setAttribute("aria-hidden","true");
  css(dot,{position:"absolute",top:"2px",right:"2px",width:"14px",height:"14px",borderRadius:"50%",background:"#EF4444",border:"2px solid #fff",display:"none"});
  btn.appendChild(dot);

  var box=document.createElement("div");
  css(box,{position:"fixed",bottom:"88px",width:"380px",height:"600px",maxWidth:"calc(100vw - 32px)",maxHeight:"calc(100vh - 108px)",borderRadius:"16px",overflow:"hidden",boxShadow:"0 12px 40px rgba(0,0,0,.28)",background:"#fff",display:"none",zIndex:z});
  box.style[side]="20px";

  function toggle(v){
    open=typeof v==="boolean"?v:!open;
    if(open&&!frame){
      frame=document.createElement("iframe");
      frame.src=base+"/chat/"+encodeURIComponent(slug)+"?embed=1";
      frame.title="Chat de soporte";
      css(frame,{width:"100%",height:"100%",border:"0"});
      box.appendChild(frame);
    }
    box.style.display=open?"block":"none";
    btn.setAttribute("aria-expanded",String(open));
    if(open){dot.style.display="none";btn.removeAttribute("data-unread");btn.setAttribute("aria-label","Cerrar chat con "+label)}
    else btn.setAttribute("aria-label","Abrir chat con "+label);
  }
  btn.addEventListener("click",function(){toggle()});
  window.addEventListener("message",function(e){
    if(e.origin!==base||!e.data)return;
    if(e.data.type==="alloxentric:close")toggle(false);
    else if(e.data.type==="alloxentric:unread"&&!open){dot.style.display="block";btn.setAttribute("data-unread","1");btn.setAttribute("aria-label","Nueva respuesta de "+label+" - abrir chat")}
  });
  document.addEventListener("keydown",function(e){if(e.key==="Escape"&&open)toggle(false)});

  function mount(){document.body.appendChild(box);document.body.appendChild(btn)}
  if(document.body)mount();else document.addEventListener("DOMContentLoaded",mount);
})();
